class Solution { public boolean isMatch(String s,String p) { boolean[] d=new boolean[p.length()+1];d[0]=true;for(int j=1;j<=p.length();j++)d[j]=d[j-1]&&p.charAt(j-1)=='*';for(int i=0;i<s.length();i++){boolean[] n=new boolean[p.length()+1];for(int j=1;j<=p.length();j++){char c=p.charAt(j-1);if(c=='*')n[j]=n[j-1]||d[j];else n[j]=d[j-1]&&(c=='?'||c==s.charAt(i));}d=n;}return d[p.length()];} }
